#include <bits/stdc++.h>
using namespace std;

class GTakeMetro {
public:
    int n, m, s;
    long long t;

    void step() {
        int curJump = (int)(t % n);
        int sign = s < m ? 1 : -1;
        s += sign * curJump;
        s %= n;
        if (s < 0) s += n;
        t--;
    }

    void doLoop() {
        for (int i = 0; i < n; i++) step();
    }

    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        string line;
        getline(cin, line);
        istringstream iss(line);
        iss >> n >> m >> s >> t;
        s -= 1;

        while ((t % n) != 0) step();

        vector<long long> lastSeem(n, -1);
        while (t != 0) {
            doLoop();
            if (lastSeem[s] != -1) {
                long long interval = lastSeem[s] - t;
                t %= interval;
                break;
            } else {
                lastSeem[s] = t;
            }
        }
        while (t != 0) step();
        cout << s + 1 << "\n";
    }
};

int main() {
    GTakeMetro solver;
    solver.solve();
    return 0;
}

